      "topicId": "programming_ide",
      "topicName": "Программаларды құрудың кіріктірілген орталары",
      "text": "Lesson study кезеңдерінің бірі - \"Қатысушылардың өткізілген сабақ бойынша оқушылардың оқу үдерісіне қатысты барлық нәтижелерін жүйелеп, талдауы\". Осыдан кейінгі кезең",
