      "topicId": "programming_ide",
      "topicName": "Программаларды құрудың кіріктірілген орталары",
      "text": "Авторитарлы тәрбие, либералды тәрбие, демократиялық тәрбие, еркін тәрбие. Қандай белгілер бойынша жіктелген",
