      "text": "Оқушыларға анағұрлым толық жауап беруге, өз ойларын анық білдіруге, идеяларын дамытуға көмектесетін, тапсырманы орындау барысында оқушыға бағдар беріп отыратын сұрақ қою тәсілі",
