      "id": "q_0692",
      "topicId": "context",
      "topicName": "Мәнмәтіндік тапсырмалар (Контекст)",
      "text": "Мектептегі әртүрлі бөлімдерді (әкімшілік және оқу сыныптары) логикалық тұрғыдан оқшаулау үшін қолданылатын технология:",
