      "contextText": "Мектептің ақпараттық жүйесіне сырттан қауіпті хакерлік шабуыл жасау әрекеті тіркелді. Әкімшілік электрондық поштасына «Шұғыл: Сіздің аккаунтыңыз бұғатталды, мына сілтеме арқылы пароліңізді жаңартыңыз» деген мазмұнда жалған хат келген. Сондай-ақ мектептің серверіне өте қысқа уақытта миллиондаған сұраныстар жіберіліп, жүйенің жұмысы баяулаған.\nЖүйелік әкімші екі факторлы аутентификацияны (2FA) енгізіп, күрделі парольдік саясат орнатты және желіаралық экран (Firewall) ережелерін күшейтті."
