      "contextText": "Мектептің ақпараттық жүйесі «Kundelik» және онлайн тестілеу платформаларымен интеграцияланған. Барлық мұғалімдер мен оқушылардың жеке мәліметтерін (ЖСН, бағалар, байланыс телефондары) қорғау үшін келесі шаралар қолға алынды:\n1. Барлық сессиялар TLS 1.3 хаттамасы арқылы шифрланады.\n2. Мұғалімдер мен директордың тоқсандық есептерге қол қоюы үшін ҚР Ұлттық куәландырушы орталығының (ҰКО / НУЦ) берген жеке ЭЦҚ кілттері пайдаланылады.\n3. Мәліметтер қорындағы құпия сөздер (парольдер) ашық түрде емес, SHA-256 бірбағытты хэш-функциясы және тұздық (salt) арқылы өңделіп сақталады.\n4. Серверге қашықтан әкімшілік ету үшін қауіпсіз SSH хаттамасы қолданылады."
