      "contextTitle": "Логикалық схемалар мен автоматтандырылған басқару жүйелері",
      "contextText": "Мектептің жылыту қазандығын автоматты түрде басқару үшін логикалық релелерден тұратын қауіпсіздік жүйесі құрылды. Жүйеде 3 датчик орнатылған:\n- A датчигі: Су температурасы 90°C-ден асқанда A = 1 болады.\n- B датчигі: Қазандықтағы қысым 3 атмосферадан асқанда B = 1 болады.\n- C датчигі: Су деңгейі қауіпті төмен түскенде C = 1 болады.\n\nАвариялық дабыл (сигнал) келесі логикалық функция бойынша қосылады:\nF = (A AND B) OR C\nЯғни, егер су температурасы мен қысым бір мезгілде шектен асса НЕМЕСЕ су деңгейі қауіпті төмендесе, дабыл қосылуы (F = 1) тиіс."
