      "contextTitle": "Векторлық және растрлық дизайн жобасы (Полиграфия)",
      "contextText": "Мектеп оқушылары «Жас дизайнер» байқауына мектептің жаңа логотипі мен мерекелік плакатын әзірледі. Жоба жетекшісі оқушыларға мынадай тапсырмалар қойды:\n1. Логотипті кез келген өлшемде (кішкентай төсбелгіден бастап үлкен билбордқа дейін) сапасын жоғалтпай басып шығару үшін векторлық CorelDRAW бағдарламасында SVG пішімінде сақтау.\n2. Фотоколлаж бен плакаттың өңін Adobe Photoshop-та 300 DPI тығыздықта, CMYK үлгісінде дайындау.\n3. Әлеуметтік желілерде жариялау үшін плакатты 1080x1080 өлшеміндегі 72 DPI, RGB түстік форматындағы JPEG файлына экспорттау."
