      "contextText": "Мектептегі серверлік бөлмеге мектептің барлық электронды базасын сақтау үшін жаңа сенімділігі жоғары сервер орнатылды. \nСерверлік конфигурация:\n- 2 дана қуатты көп ядролы Intel Xeon процессоры;\n- 64 ГБ ECC жедел жады (ECC – қателерді өздігінен түзететін жад);\n- 4 дана 2 ТБ Enterprise сыйымдылығы бар қатты дискілерден RAID 10 (1+0) массиві құрылды.\nRAID 10 массиві дискілердің біреуі немесе екеуі істен шықса да, жүйенің тоқтаусыз жұмыс істеуін және деректердің айналық көшірмесін (Mirroring) сақтауын қамтамасыз етеді."
