      "contextText": "Мектеп аумағында сымсыз интернет инфрақұрылымы жаңартылды. Бұрынғы 802.11n стандартының орнына жаңа Wi-Fi 6 (802.11ax) стандартындағы кіру нүктелері (Access Point) орнатылды.\nWi-Fi 6 технологиясының ерекшеліктері:\n- OFDMA және MU-MIMO технологиялары арқылы бір мезгілде жүздеген оқушылар мен мұғалімдердің құрылғыларына кедергісіз қызмет көрсете алады.\n- Жұмыс жиіліктері: 2.4 ГГц және 5 ГГц диапазондары.\n- Қауіпсіздік хаттамасы: Бұзылуға төзімді 192-биттік шифрлауы бар жаңа WPA3 стандарты орнатылды. WPA2-дегі сөздік шабуылдарға осал орындар WPA3-те толық шешілген."
